import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Count the number of 1s and 2s
    count_1 = a.count(1)
    count_2 = a.count(2)

    # Start with 2 to get 1 prime
    if count_2 > 0:
        result = [2]
        count_2 -= 1
    else:
        result = []

    # Alternate between 1 and 2
    for i in range(n - 1):
        if i % 2 == 0:
            # Add 1
            if count_1 > 0:
                result.append(1)
                count_1 -= 1
            else:
                # No more 1s, add 2
                result.append(2)
                count_2 -= 1
        else:
            # Add 2
            if count_2 > 0:
                result.append(2)
                count_2 -= 1
            else:
                # No more 2s, add 1
                result.append(1)
                count_1 -= 1

    print(' '.join(map(str, result)))

if __name__ == "__main__":
    solve()
"}

