def find_components(n, edges):
    graph = [[] for _ in range(n + 1)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * (n + 1)
    components = []

    for i in range(1, n + 1):
        if not visited[i]:
            stack = [i]
            visited[i] = True
            component = []
            while stack:
                node = stack.pop()
                component.append(node)
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
            components.append(component)

    return components

n = int(input())
edges = []
for _ in range(n - 1):
    u, v = map(int, input().split())
    edges.append((u, v))

components = find_components(n, edges)
c = len(components)

print(c - 1)

# Find all edges in component 0
edges_in_component_0 = []
for u, v in edges:
    if u in components[0] and v in components[0]:
        edges_in_component_0.append((u, v))

# For each operation, remove an edge from component 0 and add an edge between component 0 and component 1
for i in range(c - 1):
    remove_u, remove_v = edges_in_component_0[i % len(edges_in_component_0)]
    print(remove_u, remove_v, components[0][0], components[1][0])
"}

