import sys

def solve():
    t = int(sys.stdin.readline())

    for _ in range(t):
        # Place queen at (1, 1)
        print("1 1")
        sys.stdout.flush()

        queen_x, queen_y = 1, 1
        moves = 0

        while moves < 130:
            # Get king's move direction
            direction = sys.stdin.readline().strip()

            if direction == "Done":
                break

            # Determine new queen position
            if direction == "Left":
                # King moved left, move queen right
                queen_y += 1
            elif direction == "Right":
                # King moved right, move queen left
                queen_y -= 1
            elif direction == "Up":
                # King moved up, move queen down
                queen_x += 1
            elif direction == "Down":
                # King moved down, move queen up
                queen_x -= 1
            elif direction == "Up-Left":
                # King moved up-left, move queen down-right
                queen_x += 1
                queen_y += 1
            elif direction == "Up-Right":
                # King moved up-right, move queen down-left
                queen_x += 1
                queen_y -= 1
            elif direction == "Down-Left":
                # King moved down-left, move queen up-right
                queen_x -= 1
                queen_y += 1
            elif direction == "Down-Right":
                # King moved down-right, move queen up-left
                queen_x -= 1
                queen_y -= 1

            # Ensure queen doesn't stay in place
            if queen_x == 1 and queen_y == 1:
                queen_x = 2
            elif queen_x == 1 and queen_y == 8:
                queen_y = 7
            elif queen_x == 8 and queen_y == 1:
                queen_x = 7
            elif queen_x == 8 and queen_y == 8:
                queen_y = 7

            # Print queen's new position
            print(f"{queen_x} {queen_y}")
            sys.stdout.flush()

            moves += 1

if __name__ == "__main__":
    solve()
