{"code": "
def mex(values):
    """Compute mex (minimum excludant) of a set of integers."""
    values = set(values)
    i = 0
    while i in values:
        i += 1
    return i

# Compute Grundy numbers for logs of length m
# g[m] = Grundy number for a log of length m
# g[m] = 0 if m < k (losing position)
# g[m] = mex{ 0 if t even, g[m/t] if t odd } for all valid t

def solve():
    n, m, k = map(int, input().split())

    # Compute Grundy numbers for all lengths up to m
    g = {}
    for length in range(k, m + 1):
        # Check if we can split this log
        can_split = False
        for t in range(2, length + 1):
            if length % t == 0 and length // t >= k:
                can_split = True
                break

        if not can_split:
            g[length] = 1  # Winning position
        else:
            # Compute all possible results of splits
            results = set()
            for t in range(2, length + 1):
                if length % t == 0 and length // t >= k:
                    # Split into t parts of length length//t
                    if t % 2 == 0:
                        results.add(0)
                    else:
                        results.add(g[length // t])

            g[length] = mex(results)

    # The game state: n logs of length m
    # XOR of all n logs of length m
    # If n is even, XOR of even number of same values is 0
    # If n is odd, XOR of odd number of same values is g[m]

    if n % 2 == 0:
        xor_result = 0
    else:
        xor_result = g[m]

    if xor_result == 0:
        print("Marsel")  # First player loses
    else:
        print("Timur")  # First player wins

solve()
