    import sys
    input = sys.stdin.read
    data = input().split()

    idx = 0
    n = int(data[idx]); idx += 1
    m1 = int(data[idx]); idx += 1
    m2 = int(data[idx]); idx += 1

    uf1 = UnionFind(n)
    for _ in range(m1):
        u = int(data[idx]); idx += 1
        v = int(data[idx]); idx += 1
        uf1.union(u, v)

    uf2 = UnionFind(n)
    for _ in range(m2):
        u = int(data[idx]); idx += 1
        v = int(data[idx]); idx += 1
        uf2.union(u, v)

    # Find all component pairs
    component_map1 = {}
    component_map2 = {}

    for i in range(1, n + 1):
        comp1 = uf1.find(i)
        comp2 = uf2.find(i)

        if comp1 not in component_map1:
            component_map1[comp1] = []
        component_map1[comp1].append(i)

        if comp2 not in component_map2:
            component_map2[comp2] = []
        component_map2[comp2].append(i)

