        row1 = list(map(int, input().split()))
        row2 = list(map(int, input().split()))

        # DP table: dp[i][j] = optimal score when at position (i, j)
        # i=0 for row 1, i=1 for row 2
        dp = [[0] * m for _ in range(2)]

        # Base case: starting at (0, 0)
        dp[0][0] = row1[0]

        # Fill DP table
        for i in range(2):
            for j in range(1, m):
                # From left (if we came from the same row)
                if i == 0:
                    dp[i][j] = max(dp[i][j-1] + row1[j], dp[i][j])
                else:
                    dp[i][j] = max(dp[i][j-1] + row2[j], dp[i][j])

                # From above (if we came from the other row)
                if i == 1:
                    dp[i][j] = max(dp[i][j], dp[i-1][j] + row2[j])
                else:
                    dp[i][j] = max(dp[i][j], dp[i-1][j] + row1[j])

