        row2 = list(map(int, input().split()))

        # DP table: dp[i][j] = optimal score when at position (i, j)
        # i=0 for row 1, i=1 for row 2
        # dp[i][j] = max score Bob can get from (i, j) to (2, m)
        dp = [[0] * m for _ in range(2)]

        # Base case: at (2, m)
        dp[1][m-1] = 0

        # Fill DP table from right to left
        for j in range(m-2, -1, -1):
            for i in range(2):
                # From right (if we came from the same row)
                if i == 0:
                    dp[i][j] = max(dp[i][j+1] + row1[j], dp[i][j])
