    data = sys.stdin.read().split()

    if not data:
        return

    idx = 0
    N = int(data[idx])
    Q = int(data[idx+1])
    idx += 2

    words = []
    for _ in range(N):
        words.append(data[idx])
        idx += 1

    # Build prefix dictionary
    prefix_dict = {}
    for word in words:
        for i in range(1, len(word) + 1):
            prefix = word[:i]
            if prefix not in prefix_dict:
                prefix_dict[prefix] = []
            prefix_dict[prefix].append(word)

    # Process queries
    output = []
    for _ in range(Q):
        p = data[idx]
        s = data[idx+1]
        idx += 2

        count = 0
        for word in prefix_dict.get(p, []):
            if word.endswith(s):
                count += 1
        output.append(str(count))

    print("\n".join(output))

if __name__ == "__main__":
    solve()

