import sys

def find_cycle(graph, n):
    """Find a cycle in the graph."""
    visited = [False] * (n + 1)
    path = []

    def dfs(v):
        if visited[v]:
            if v in path:
                # Found a cycle
                idx = path.index(v)
                cycle = path[idx:]
                return cycle
            return None

        visited[v] = True
        path.append(v)

        for neighbor in graph[v]:
            result = dfs(neighbor)
            if result:
                return result

        path.pop()
        return None

    for i in range(1, n + 1):
        result = dfs(i)
        if result:
            return result

    return None

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    graph = [[] for _ in range(n + 1)]
    idx = 2

    for _ in range(m):
        a = int(data[idx])
        b = int(data[idx + 1])
        graph[a].append(b)
        idx += 2

    cycle = find_cycle(graph, n)

    if not cycle:
        print(-1)
    else:
        print(len(cycle))
        for v in cycle:
            print(v)

if __name__ == "__main__":
    solve()
