        idx += 1
        a = list(map(int, data[idx:idx+n]))
        idx += n

        evens = []
        odds = []

        for num in a:
            if num % 2 == 0:
                evens.append(num)
            else:
                odds.append(num)

        # Check if it's possible
        if abs(len(evens) - len(odds)) > 1:
