        # Calculate minimal swaps
        # We need to interleave them
        # The pattern could be even-odd-even-odd... or odd-even-odd-even...
        # Let's try both patterns and take the minimum

        # Pattern 1: even-odd-even-odd...
        swaps1 = 0
        i = 0
        for j in range(n):
            if j % 2 == 0:
                # Expected even
                if i < len(evens) and evens[i] % 2 == 0:
                    i += 1
                else:
                    swaps1 += 1
            else:
                # Expected odd
                if i < len(odds) and odds[i] % 2 == 1:
                    i += 1
                else:
                    swaps1 += 1

        # Pattern 2: odd-even-odd-even...
