def solve():
    import sys
    input = sys.stdin.read()
    data = input.split()

    if not data:
        return

    idx = 0
    N = int(data[idx])
    idx += 1
    L = int(data[idx])
    idx += 1

    A = list(map(int, data[idx:idx+N]))

    # Precompute p_max for all i from 1 to L
    p_max = [0] * (L + 1)  # 1-indexed

    for i in range(1, L + 1):
        # Find prime factorization of i
        prime_factors = {}
        temp = i

        # Check primes up to sqrt(temp)
        for p in range(2, int(temp**0.5) + 1):
            if temp % p == 0:
                cnt = 0
                while temp % p == 0:
                    cnt += 1
                    temp //= p
                prime_factors[p] = cnt

        # If remaining temp > 1, it's a prime factor
        if temp > 1:
            prime_factors[temp] = 1

        if not prime_factors:
            p_max[i] = 0  # i = 1
        else:
            # Find prime with max exponent (and smallest prime if tie)
            max_exp = -1
            p_max_val = 0
            for p, exp in prime_factors.items():
                if exp > max_exp or (exp == max_exp and p < p_max_val):
                    max_exp = exp
                    p_max_val = p
            p_max[i] = p_max_val

    # Process operations
    for i in range(1, L + 1):
        if not A:
            break

        if i == 1 or (p_max[i] % i) % 2 == 1:
            # Beneficial: double the smallest element
            if A:
                min_val = min(A)
                idx_min = A.index(min_val)
                A[idx_min] *= 2
        else:
            # Harmful: divide the largest element by 2
            if A:
                max_val = max(A)
                idx_max = A.index(max_val)
                A[idx_max] //= 2

        # Remove elements that became 0
        A = [x for x in A if x != 0]

    # Output
    print(len(A))
    if A:
        print(' '.join(map(str, sorted(A))))
    else:
        print()

solve()
