    dot_product = ba[0] * bc[0] + ba[1] * bc[1]

    # If dot product is negative, angle > 90 degrees
    return dot_product >= 0

def proportion_condition(seg, point):
    """Check if point divides segment in proportion ≥ 1/4"""
    a, b = seg
    pa = dist_sq(a, point)
    pb = dist_sq(b, point)

    # Find the shorter and longer parts
    if pa < pb:
        shorter = pa
        longer = pb
    else:
        shorter = pb
        longer = pa

    # Check proportion condition
    return shorter / longer >= 1/4

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    t = int(data[0])
    idx = 1

    for _ in range(t):
        # Read three segments
        segments = []
        for _ in range(3):
            x1, y1, x2, y2 = map(int, data[idx:idx+4])
            segments.append(((x1, y1), (x2, y2)))
            idx += 4

        # Check all permutations
        found = False
        for i in range(3):
            for j in range(3):
                if i == j:
                    continue

                # First segment: segments[i], second segment: segments[j]
                seg1 = segments[i]
                seg2 = segments[j]
                seg3 = segments[3 - i - j]

                # Find common endpoint
                common = None
                for p1 in seg1:
                    for p2 in seg2:
                        if p1 == p2:
                            common = p1
                            break
                    if common:
                        break

                if not common:
                    continue

                # Check if third segment connects two points on different segments
                # Find points on seg1 and seg2
                p1_on_seg1 = None
                p2_on_seg2 = None

                for p in seg3:
                    if is_point_on_segment(p, seg1[0], seg1[1]):
                        p1_on_seg1 = p
                    elif is_point_on_segment(p, seg2[0], seg2[1]):
                        p2_on_seg2 = p

                if not p1_on_seg1 or not p2_on_seg2:
                    continue

                # Check angle condition
                if not angle_condition(seg1[0], common, seg1[1]):
                    continue

                # Check proportion conditions
                if proportion_condition(seg1, p1_on_seg1) and proportion_condition(seg2, p2_on_seg2):
                    found = True
                    break
            if found:
                break

        print("YES" if found else "NO")

if __name__ == "__main__":
    solve()

