def find_minimal_segment(n, k, a):
    from collections import defaultdict

    freq = defaultdict(int)
    distinct = 0

    # Expand window to find a window with exactly k distinct elements
    left = 0
    for right in range(n):
        freq[a[right]] += 1
        if freq[a[right]] == 1:
            distinct += 1

        # If we have more than k distinct, move left pointer
        while distinct > k:
            freq[a[left]] -= 1
            if freq[a[left]] == 0:
                distinct -= 1
            left += 1

        # If we have exactly k distinct, check if it's minimal by inclusion
        if distinct == k:
            # Try to shrink from the left
            while left < right and distinct == k:
                # Check if we can remove a[left] and still have k distinct
                if freq[a[left]] > 1:
                    freq[a[left]] -= 1
                    left += 1
                else:
                    break

            # Now check if we can shrink from the right
            while left < right and distinct == k:
                # Check if we can remove a[right] and still have k distinct
                if freq[a[right]] > 1:
                    freq[a[right]] -= 1
                    right -= 1
                else:
                    break

            # If we still have exactly k distinct, this is a minimal window
            if distinct == k:
                return (left + 1, right + 1)  # Convert to 1-indexed

    return -1, -1

