import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # For each bit position, collect nodes that have that bit set
    bit_nodes = [[] for _ in range(61)]  # 0 to 60

    for i in range(n):
        for b in range(61):
            if a[i] & (1 << b):
                bit_nodes[b].append(i)

    min_cycle = -1

    # Check for cycles of length 3
    for b in range(61):
        if len(bit_nodes[b]) >= 3:
            min_cycle = 3
            break

    # Check for cycles of length 4
    if min_cycle == -1:
        for b in range(61):
            if len(bit_nodes[b]) >= 4:
                min_cycle = 4
                break

    if min_cycle == -1:
        # Check for cycles of length 4 using two different bits
        for b1 in range(61):
            for b2 in range(b1 + 1, 61):
                # Find nodes that have both bits b1 and b2 set
                common = []
                for i in bit_nodes[b1]:
                    if a[i] & (1 << b2):
                        common.append(i)
                if len(common) >= 2:
                    min_cycle = 4
                    break
            if min_cycle != -1:
                break

    print(min_cycle)

if __name__ == "__main__":
    solve()
