MOD = 1000000007

# Precompute factorials and inverse factorials up to 10^5
max_n = 100000
fact = [1] * (max_n + 1)
in_fact = [1] * (max_n + 1)

for i in range(1, max_n + 1):
    fact[i] = fact[i-1] * i % MOD

inv_fact = [1] * (max_n + 1)
inv_fact[max_n] = pow(fact[max_n], MOD-2, MOD)
for i in range(max_n-1, -1, -1):
    inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

def comb(n, k):
    """n choose k modulo MOD"""
    if n < 0 or k < 0 or k > n:
        return 0
    return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD

# Precompute smallest prime factor (SPF) for sieve of Eratosthenes
spf = list(range(max_n + 1))
for i in range(2, int(max_n**0.5) + 1):
    if spf[i] == i:
        for j in range(i*i, max_n + 1, i):
            if spf[j] == j:
                spf[j] = i

# Function to get all divisors of a number
def get_divisors(n):
    divisors = set()
    if n == 1:
        return divisors

    # Get prime factorization
    factors = {}
    while n > 1:
        p = spf[n]
        count = 0
        while n % p == 0:
            n //= p
            count += 1
        factors[p] = count

    # Generate all divisors
    divisors = [1]
    for p, exp in factors.items():
        temp = []
        for d in divisors:
            for e in range(1, exp + 1):
                temp.append(d * (p**e))
        divisors += temp

    return divisors

q = int(input())
